package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class MathUtils_factorialLog_TriageGen0Test {

    private static final double DELTA = 1e-12;











    @Test
    public void testFactorialLog_LargeN() {
        // n >= 21 branch: uses loop sum of logs
        // n = 21: log(21!) = log(1) + log(2) + ... + log(21)
        double expectedLogSum = 0;
        for (int i = 2; i <= 21; i++) {
            expectedLogSum += Math.log((double) i);
        }
        assertEquals(expectedLogSum, MathUtils.factorialLog(21), DELTA);
    }


}

package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class MathUtils_factorialLog_TriageGen0Test {

    private static final double DELTA = 1e-12;













    @Test
    public void testFactorialLog_VeryLargeN() {
        // Test higher value to ensure loop works correctly
        int n = 50;
        double expectedLogSum = 0;
        for (int i = 2; i <= n; i++) {
            expectedLogSum += Math.log((double) i);
        }
        assertEquals(expectedLogSum, MathUtils.factorialLog(n), DELTA);
    }
}
